SELECT CASE WHEN quantity >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, ROUND(AVG(quantity), 2) AS avg_quantity, ROUND(AVG(quantity), 2) AS avg_quantity_2, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, ROUND(AVG(quantity), 2) AS avg_quantity_3 FROM order_items GROUP BY CASE WHEN quantity >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_quantity_3 ASC NULLS LAST;
